 .select2-selection--multiple .select2-selection__rendered{display:flex!important;align-items:center!important;flex-wrap:wrap!important;gap:4px!important;margin:0!important;padding:0!important}.jr-page .select2-container--default .select2-selection--multiple .select2-selection__choice{margin:0!important;padding:3px 8px 3px 24px!important;border:1px solid #dbe5d5!important;border-radius:999px!important;background:#f1f7ed!important;color:#315445!important;font-size:12px!important;line-height:20px!important;position:relative!important}.jr-page .select2-container--default .select2-selection--multiple .select2-selection__choice__remove{position:absolute!important;left:7px!important;top:50%!important;transform:translateY(-50%)!important;border:0!important;color:#718692!important;background:transparent!important}.jr-page .select2-container--default .select2-selection--multiple .select2-search--inline .select2-search__field{height:30px!important;margin:0!important;padding:4px 2px!important;border:0!important;box-shadow:none!important;font-size:14px!important}.jr-page .jr-assessment-col .select2-container{max-width:100%!important}.jr-page .jr-assessment-col .select2-selection--multiple{min-height:48px!important}

