.jr-modal-btn{height:38px;padding:0 14px;border:1px solid var(--jr-line);border-radius:7px;background:#fff;color:#31505d;font:700 14px Arial,Helvetica,sans-serif;cursor:pointer}.jr-modal-btn.primary{border-color:var(--jr-green);background:var(--jr-green);color:var(--jr-button-text)}.jr-modal-btn.primary:hover{background:var(--jr-green-dark)}.jr-modal-btn:disabled{opacity:.55;cursor:not-allowed}
