function money(v){var p=parseInt((meta.currency||{}).decimal_places,10);if(isNaN(p))p=2;var n=Number(v||0).toFixed(p),s=(meta.currency||{}).symbol||'';return (meta.currency||{}).symbol_position==='after'?n+(s?' '+s:''):(s||'')+n}
