function lineHtml(x){x=x||{};lineSeq++;var id='rli'+lineSeq;return '<div class="jr-line" data-line="'+id+'"><div class="jr-line-item"><select class="jr-line-select" data-f="catalog">'+catalogOptions(x.product_service_id||0)+'</select></div><div class="jr-money"><small>Quantity</small><input data-f="qty" type="number" min="0.001" step="0.001" value="'+Number(x.quantity||1)+'"></div><div class="jr-money"><small>Unit price</small><input data-f="price" type="number" min="0" step="0.01" value="'+Number(x.unit_price||0).toFixed(2)+'"></div><div class="jr-money"><small>Total</small><strong data-f="total">'+money(Number(x.quantity||1)*Number(x.unit_price||0))+'</strong></div><div class="jr-line-actions"><button type="button" class="jr-line-more" title="More actions"><i class="bi bi-three-dots"></i></button><div class="jr-line-menu"><button type="button" data-line-action="delete"><i class="bi bi-trash"></i> Delete</button></div></div><textarea class="jr-control jr-line-desc" data-f="desc" placeholder="Description">'+esc(x.description||'')+'</textarea><label class="jr-line-image"><i class="bi bi-image"></i><input type="file" name="line_item_images[]" accept="image/*"></label></div>'}
function addLine(x){E('lineItems').insertAdjacentHTML('beforeend',lineHtml(x));var r=E('lineItems').lastElementChild,$s=$(r).find('.jr-line-select');$s.select2({width:'100%',dropdownCssClass:'jr-request-select2-dropdown',placeholder:'Name',allowClear:true,tags:true,minimumResultsForSearch:0,createTag:function(params){var term=$.trim(params.term||'');if(!term)return null;var exact=(meta.catalog||[]).some(function(v){return String(v.name||'').toLowerCase()===term.toLowerCase()});return exact?null:{id:'newitem:'+term,text:term,newTag:true}},templateResult:catalogResult,templateSelection:catalogSelection});$s.on('select2:select',function(e){var raw=String(e.params&&e.params.data?e.params.data.id:this.value||'');if(raw.indexOf('newitem:')===0){catalogTargetRow=r;openCreateCatalogModal(raw.slice(8));$s.val(null).trigger('change.select2');return}var c=catalogById(raw);if(c){r.querySelector('[data-f="price"]').value=Number(c.unit_price||0).toFixed(2);r.querySelector('[data-f="desc"]').value=c.description||'';updateLine(r)}});$s.on('select2:clear',function(){r.querySelector('[data-f="price"]').value='0.00';r.querySelector('[data-f="desc"]').value='';updateLine(r)});r.querySelector('[data-f="qty"]').oninput=function(){updateLine(r)};r.querySelector('[data-f="price"]').oninput=function(){updateLine(r)};var more=r.querySelector('.jr-line-more'),menu=r.querySelector('.jr-line-menu');more.onclick=function(e){e.stopPropagation();document.querySelectorAll('.jr-line-menu.show').forEach(function(m){if(m!==menu)m.classList.remove('show')});menu.classList.toggle('show')};r.querySelector('[data-line-action="delete"]').onclick=function(){if($s.hasClass('select2-hidden-accessible'))$s.select2('destroy');if(catalogTargetRow===r)catalogTargetRow=null;r.remove();updateTotals()};E('emptyLines').style.display='none';updateLine(r)}
